  const filtered = useMemo(
    () => filterCommodities({ stage, sector, direction }),
    [stage, sector, direction],
  );

  const ladderBars = useMemo(() => {
    return [...filtered]
      .map((c) => ({
        ...c,
        value:
          metric === "top1"
            ? c.top1SharePct
            : metric === "top3"
              ? c.top3SharePct
              : c.hhi,
