      .sort((a, b) => b.value - a.value);
  }, [filtered, metric]);

  const vintageBars = useMemo(() => {
    return VINTAGE_DELTA.filter((d) => {
      if (stage !== "all" && d.stage !== stage) return false;
      if (direction !== "all" && d.direction !== direction) return false;
      return true;
    }).slice(0, 12);
