                  <XAxis
                    type="number"
                    dataKey="reliance"
                    name="US reliance %"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                  />
                  <YAxis
                    type="number"
                    dataKey="top1"
                    name="Top-1 %"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                  />
                  <ZAxis type="number" dataKey="z" range={[40, 200]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      typeof v === "number" ? fmtPct(v, 1) : String(v),
                      String(name),
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.shortLabel ?? ""
                    }
                  />
                  <Scatter data={riskScatter}>
                    {riskScatter.map((d) => (
                      <Cell key={d.shortLabel} fill={d.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Downstream disruption risk"
            subtitle="IEA dollar framing beside Top-1 share"
          >
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={DOWNSTREAM_RISK}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="shortLabel" tick={{ fontSize: 11 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Risk $bn",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Bar
                    yAxisId="left"
                    dataKey="riskUsdBn"
                    name="Risk $bn"
                    radius={[4, 4, 0, 0]}
                  >
                    {DOWNSTREAM_RISK.map((d) => (
                      <Cell key={d.id} fill={d.fill} />
                    ))}
                  </Bar>
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="top1Pct"
                    stroke={SLATE}
                    strokeWidth={2}
                    name="Top-1 %"
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Graphite anode disruption ~${HEADLINE.graphiteDownstreamRiskUsdBn}
              B/yr outside China; REE full-chain path framed near $
              {HEADLINE.reeDownstreamRiskUsdTn}T.
            </p>
          </ChartCard>

          <ChartCard
            title="Investment YoY while the tip stays hot"
            subtitle="Capex pullback vs public-finance surge (IEA)"
          >
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={INVESTMENT_CONTEXT}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 9 }} interval={0} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(v) =>
                      typeof v === "number" ? `${v > 0 ? "+" : ""}${v}%` : String(v)
                    }
                  />
                  <Bar dataKey="yoyPct" radius={[4, 4, 0, 0]}>
                    {INVESTMENT_CONTEXT.map((d) => (
                      <Cell
                        key={d.id}
                        fill={d.yoyPct >= 0 ? TEAL : ROSE}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

